const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Keeps native debug symbols in the Android release bundle, so Play Console can turn native
 * crashes and ANRs into function names instead of addresses (and stops warning that none
 * were uploaded). `SYMBOL_TABLE` is enough for names and keeps the upload small; the app
 * people download is the same size either way. `android/` is generated by prebuild, so this
 * is where the setting lives.
 */
const LEVEL = 'SYMBOL_TABLE';

module.exports = function withNativeDebugSymbols(config) {
  return withAppBuildGradle(config, (mod) => {
    const gradle = mod.modResults.contents;
    if (gradle.includes('debugSymbolLevel')) return mod;
    if (!/defaultConfig\s*\{/.test(gradle)) {
      throw new Error(
        'withNativeDebugSymbols: no defaultConfig block in android/app/build.gradle',
      );
    }
    mod.modResults.contents = gradle.replace(
      /defaultConfig\s*\{/,
      (block) => `${block}\n        ndk { debugSymbolLevel '${LEVEL}' }`,
    );
    return mod;
  });
};
